using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Windows.Forms;
internal static class WizardQa
{
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Directory.CreateDirectory(args[0]);foreach(string lang in new string[]{"ru","de","en"})using(ConnectionWizard form=new ConnectionWizard(lang)){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.ShowInTaskbar=false;form.Show();Application.DoEvents();using(Bitmap image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(args[0],"browser-setup-"+lang+".png"),ImageFormat.Png);}foreach(Control c in form.Controls){Label label=c as Label;if(label!=null&&label.Visible&&label.Text.Length>0){Size need=TextRenderer.MeasureText(label.Text,label.Font,new Size(label.Width,1000),TextFormatFlags.WordBreak);if(need.Height>label.Height+8)throw new Exception("Clipped label "+lang+": "+label.Text);}}}Console.WriteLine("PASS: RU/DE/EN browser wizard rendered; label bounds checked");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
